    for top in range(h):
        for bottom in range(top + 3, h):
            for left in range(w):
                for right in range(left + 3, w):
                    if not all(grid[top][c] != bg and grid[bottom][c] != bg
                               for c in range(left, right + 1)):
                        continue
                    if not all(grid[r][left] != bg
                               for r in range(top + 1, bottom)):
                        continue
                    # Right side is an open mouth; require no right-wall stroke
                    # in the interior, distinguishing this U from closed loops.
                    if any(grid[r][right] != bg
                           for r in range(top + 1, bottom)):
                        continue
                    area = (bottom - top - 1) * (right - left)
                    if area <= 0:
                        continue
                    # Choose the smallest U cavity, keeping the top/bottom and
                    # left boundary pixels intact.
                    for r in range(top + 1, bottom):
                        for c in range(left + 1, right + 1):
                            if grid[r][c] == bg:
                                out[r][c] = 4
                    return out
    return out


